from datetime import timedelta
from temporalio import workflow
from temporalio.common import RetryPolicy

@workflow.defn
class TriageWorkflow:
    @workflow.run
    async def run(self, ticket_id: str) -> str:
        opts = dict(
            start_to_close_timeout=timedelta(minutes=2),
            retry_policy=RetryPolicy(maximum_attempts=4),
        )
        messages = [ticket_id]
        for step in range(8):
            reply = await workflow.execute_activity("call_model", messages, **opts)
            if not reply.get("tool"):
                return reply["text"]
            key = f"{workflow.info().workflow_id}-{step}"
            messages.append(await workflow.execute_activity("run_tool", [reply, key], **opts))
        return "escalated"
